 const emptyScope = (snapshot: string): ScopeTree => ({ snapshot, expanded: new Set(), folders: new Map(), handled: "" });

 /**
  * The explorer's tree data: per scope, the expanded folders, the loaded pages of each parent and
  * what the tree last revealed. A new snapshot drops loaded children and every pending answer and
  * keeps the expanded set; the tree re-reads what it shows. A cursor is only ever sent for the
  * snapshot that issued it. At most `MAX_TREE_READS` reads run at once. `onStale` is told when a read
  * answers `stale-snapshot` (the transport's answer to a reply for another snapshot) or, from a
  * `request` that does not check, a page of another snapshot; that page is never shown, and the read
  * is parked as stale until `reload` changes, which re-reads it under the snapshot then current.
  */
 export function useMetaprojectTree({ cwd, snapshot, request, onStale, reload, wait = sleep }: {
   cwd: string;
   snapshot: string;
   request: RequestTree;
   onStale: () => void;
   /**
    * Changes whenever the explorer loads its catalog (Refresh catalog included), whether or not the
-   * snapshot changed: parked stale reads are sent again then.
+   * snapshot changed: parked stale reads are sent again then. Required: a change of it is the only way
+   * out of a stale read, which offers no Retry.
    */
-  reload?: unknown;
+  reload: unknown;
   /** Waits before a permit retry; tests pass one that does not use the clock. */
   wait?: (ms: number) => Promise<void>;
 }): MetaprojectTreeModel {
   const [, render] = useReducer((value: number) => value + 1, 0);
   const state = useRef<Record<MetaprojectTreeScope, ScopeTree>>({ graph: emptyScope(snapshot), wiki: emptyScope(snapshot) });
   // Every snapshot change retires the answers still in flight; a read keeps the generation it started in.
   const generation = useRef(0);
   if (state.current.graph.snapshot !== snapshot) {
     generation.current++;
     const keep = (scope: ScopeTree): ScopeTree => ({ ...emptyScope(snapshot), expanded: scope.expanded, handled: scope.handled });
     state.current = { graph: keep(state.current.graph), wiki: keep(state.current.wiki) };
   }
   const latest = useRef({ cwd, request, onStale, wait });
   latest.current = { cwd, request, onStale, wait };

   const update = useCallback((scope: MetaprojectTreeScope, change: (tree: ScopeTree) => ScopeTree) => {
     const next = change(state.current[scope]);
     if (next === state.current[scope]) return;
     state.current = { ...state.current, [scope]: next };
     render();


   test("a typed CLI error on a tree read keeps its code", async () => {
     const error = await readError(requestMetaprojectTree("/checkout", { scope: "graph", parent: "gone" }, async () => {
       throw new Error("not-found: Unknown Metaproject tree parent.");
     }));
     expect(error instanceof MetaprojectRequestError && error.code).toBe("not-found");
   });

   test("Desktop's permit refusal reaches the caller recognisable as one, and other unavailable answers do not", async () => {
     // The exact text `ReadPermit::acquire` returns in src-tauri/src/metaproject.rs.
     const refusal = await readError(requestMetaprojectTree("/checkout", { scope: "graph" }, async () => {
       throw new Error("unavailable: Too many Metaproject reads. Retry shortly.");
     }));
     expect(isMetaprojectPermitRefusal(refusal)).toBe(true);
     expect(isMetaprojectPermitRefusal(new Error(METAPROJECT_PERMIT_REFUSAL))).toBe(true);
     const other = await readError(requestMetaprojectTree("/checkout", { scope: "graph" }, async () => {
       throw new Error("unavailable: The selected CLI did not complete the Metaproject read.");
     }));
     expect(isMetaprojectPermitRefusal(other)).toBe(false);
     expect(isMetaprojectPermitRefusal(new MetaprojectRequestError("not-found", "Too many Metaproject reads."))).toBe(false);
+    // A typed answer is the CLI's, never Desktop's permit refusal, even when its text reads like one.
+    expect(isMetaprojectPermitRefusal(new MetaprojectRequestError("not-found", METAPROJECT_PERMIT_REFUSAL))).toBe(false);
   });

   test("an answer for another snapshot than the one pinned is refused as stale-snapshot", async () => {
     const other = "c".repeat(64);
     const treeError = await readError(requestMetaprojectTree("/checkout", { scope: "graph", parent: "src", expectedSnapshotId: digest },
       async () => ({ ...graphRoot, snapshotId: other, parent: "src", entries: [{ type: "node", node: file }] })));
     expect(treeError instanceof MetaprojectRequestError && treeError.code).toBe("stale-snapshot");
     const searchError = await readError(requestMetaprojectV2("/checkout", { version: 2, action: "search", query: "x", cursor: "c", expectedSnapshotId: digest },
       async () => ({ schemaVersion: 2, snapshotId: other, hits: [], partial: false })));
     expect(searchError instanceof MetaprojectRequestError && searchError.code).toBe("stale-snapshot");
   });
 });
